def dstr(ts): return ts[:10]
def hour(ts): return int(ts[11:13])
def weekday(ts):
    y,m,dd=map(int, ts[:10].split('-'))
    return calendar.weekday(y,m,dd)  # Mon=0
def occupied(ts):
    h=hour(ts)
    if weekday(ts)>=5: return False
    return 7<=h<18

